use std :: time :: Duration ; use backon :: { ExponentialBuilder , Retryable } ; use forge_config :: RetryConfig ; use forge_domain :: Error ; # [doc = " Determines if an error should trigger a retry attempt."] # [doc = ""] # [doc = " This function checks if the error is a retryable domain error."] # [doc = " Currently, only `Error::Retryable` errors will trigger retries."] fn should_retry (error : & anyhow :: Error) -> bool { error . downcast_ref :: < Error > () . is_some_and (| error | matches ! (error , Error :: Retryable (_))) }